"code": "import { weekDates } from './store.js';

const WEEKDAYS = ['일', '월', '화', '수', '목', '금', '토'];

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const month = d.getMonth() + 1;
  const day = d.getDate();
  const weekday = WEEKDAYS[d.getDay()];
  return `${month}월 ${day}일 ${weekday}요일`;
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

export function renderPlanner({ tasks, selectedDate, error }) {
  const dateEl = document.getElementById('selected-date');
  const weekStrip = document.getElementById('week-days');
  const emptyState = document.getElementById('empty-state');
  const pageError = document.getElementById('page-error');
  const studyList = document.getElementById('study-items');
  const lifeList = document.getElementById('life-items');
  const template = document.getElementById('task-template');

  if (dateEl) dateEl.textContent = formatDate(selectedDate);

  if (pageError) {
    pageError.textContent = error || '';
    pageError.hidden = !error;
  }

  const dates = weekDates(selectedDate);
  if (weekStrip) {
    weekStrip.innerHTML = '';
    dates.forEach(date => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'day-button';
      btn.dataset.date = date;
      btn.setAttribute('aria-pressed', date === selectedDate ? 'true' : 'false');
      btn.setAttribute('aria-label', formatDate(date));

      const weekdaySpan = document.createElement('span');
      weekdaySpan.className = 'weekday';
      weekdaySpan.textContent = formatDate(date).split(' ')[3];

      const daySpan = document.createElement('span');
      daySpan.className = 'day-number';
      daySpan.textContent = formatDate(date).split(' ')[1].replace('일', '');

      btn.appendChild(weekdaySpan);
      btn.appendChild(daySpan);
      weekStrip.appendChild(btn);
    });
  }

  const dayTasks = tasks.filter(t => t.date === selectedDate);
  if (emptyState) {
    emptyState.hidden = dayTasks.length > 0;
  }

  const studyTasks = dayTasks.filter(t => t.category === 'study');
  const lifeTasks = dayTasks.filter(t => t.category === 'life');

  function renderList(listEl, taskList) {
    listEl.innerHTML = '';
    taskList.forEach(task => {
      const clone = template.content.cloneNode(true);
      const li = clone.querySelector('li');
      const checkbox = clone.querySelector('.task-check');
      const nameEl = clone.querySelector('.task-name');
      const deleteBtn = clone.querySelector('.delete-task');

      li.dataset.id = task.id;
      if (task.completed) {
        li.classList.add('is-complete');
      }
      checkbox.checked = task.completed;
      nameEl.textContent = task.title;
      deleteBtn.setAttribute('aria-label', `${task.title} 삭제`);

      listEl.appendChild(clone);
    });
  }

  renderList(studyList, studyTasks);
  renderList(lifeList, lifeTasks);
}"
}
